function modal(title,body,footer='',options={}){if(modalClose)modalClose();const el=document.createElement('div');el.className='modalback';el.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modalheader"><h2>${title}</h2><button class="close" aria-label="Close">×</button></div><div class="modalbody">${body}<div id="modalerror"></div></div>${footer?`<div class="modalfooter">${footer}</div>`:''}</section>`;document.body.append(el);const prior=document.activeElement;let cleanup;modalClose=()=>{cleanup?.();el.remove();modalClose=null;prior?.focus();document.removeEventListener('keydown',keys);if(pendingBackground)queueMicrotask(()=>{if(actor&&!modalClose)load({background:true});});};const keys=e=>{if(e.key==='Escape'&&!options.persistent)modalClose?.();if(e.key==='Tab'){const all=$$('button,input,select,textarea,a[href]',el).filter(x=>!x.disabled&&!x.closest('.hidden'));if(e.shiftKey&&document.activeElement===all[0]){e.preventDefault();all.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===all.at(-1)){e.preventDefault();all[0]?.focus();}}};document.addEventListener('keydown',keys);$('.close',el).onclick=()=>modalClose();el.addEventListener('click',e=>{if(e.target===el&&!options.persistent)modalClose?.();});setTimeout(()=>$('input,select,button',el)?.focus(),0);return {el,onClose:fn=>cleanup=fn};}
async function action(fn){if(busy)return;busy=true;try{await fn();}catch(e){const target=$('#modalerror');if(target)target.innerHTML=`<div class="error">${esc(e.message)}</div>`;else toast(e.message);}finally{busy=false;}}
