async function load({background=false}={}){if(!actor)return;if(background&&modalClose){pendingBackground=true;return;}const user=actor,state=await store.view(user),items=await store.get('queue')||[];if(actor!==user)return;if(background&&modalClose){pendingBackground=true;return;}pendingBackground=false;fullState=state;s=reviewState(fullState);queue=items.filter(x=>x.actorId===actor.id);render();store.watch(actor,()=>{if(actor)load({background:true});});}
