function loginView(){const demo=store.currentMode()==='demo';const preferences=readLoginPreferences(portal);document.body.className=portal==='admin'?'admin-entry':'mobile-entry';$('#app').innerHTML=`<div class="login"><section class="loginart">${brand}<div><div class="eyebrow" style="color:#aabf9b">PACKING OPERATIONS, CONNECTED</div><h1>Every delivery.<br>Every piece.<br><span>All accounted for.</span></h1><p>A clearer workday for your logistics staff, packers and administration team.</p><div class="steps"><span>01 &nbsp; Deliver</span><span>02 &nbsp; Collect</span><span>03 &nbsp; Confirm</span></div></div><small style="color:#aabf9b">One connected workflow. From the road to month-end.</small></section><section class="loginform"><div class="logincard"><div class="eyebrow">${portal==='admin'?'PACKFLOW ADMIN':'LOGISTICS / PACKER APP'} · v0.15</div><h1>${portal==='admin'?'Admin Login':'Welcome back.'}</h1><p class="muted">${portal==='admin'?'K&H Wholesale Trading':'Sign in with your assigned ID and password.'}</p><div class="portal-links"><a href="/admin.html">PC Admin</a><a href="/mobile.html">Logistics / Packer</a></div><p></p>${demo&&portal==='all'?`<div class="loginroles"><button class="active" data-id="ADMIN">${icon('grid')}Administration</button><button data-id="DRV01">${icon('truck')}Logistics</button><button data-id="PK01">${icon('box')}Packer</button></div>`:''}<form id="loginform">${portal==='admin'?'<input type="hidden" id="loginid" name="username" autocomplete="username" value="ADMIN">':field('USER ID','loginid',preferences.rememberId?preferences.id:(demo?'ADMIN':''),'text','name="username" autocomplete="username" required')}<div class="field"><label for="loginpassword">PASSWORD</label><div class="password-control"><input id="loginpassword" name="password" type="password" autocomplete="current-password" value="${demo?'demo123':''}" required><button type="button" id="togglepassword" aria-label="Show password" aria-pressed="false" aria-controls="loginpassword">Show</button></div></div><div class="remember-options"><label ${portal==='admin'?'hidden':''}><input type="checkbox" id="rememberid" ${preferences.rememberId?'checked':''}> Remember ID</label><label><input type="checkbox" id="rememberpassword" ${preferences.rememberPassword?'checked':''}> Remember password</label></div><p class="login-help">Passwords are saved by your browser password manager, with your approval.</p><div id="loginerror"></div><button class="btn primary" style="width:100%" type="submit">${portal==='admin'?'Sign In':'Sign in to workspace '+icon('arrow')}</button></form>${demo?'<div class="notice warn" style="margin-top:23px">Demo workspace · Sample records only.<br>No Firebase project connected. Password: demo123</div>':''}<p class="disclaimer">Accounts are managed by your administrator. Contact them for access or password assistance.</p></div></section></div>`;$$('[data-id]').forEach(b=>b.onclick=()=>{$$('[data-id]').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#loginid').value=b.dataset.id;});if(demo&&portal!=='all'&&!preferences.rememberId){$('#loginid').value=portal==='admin'?'ADMIN':portal==='driver'||portal==='mobile'?'DRV01':'PK01';$$('[data-id]').forEach(b=>b.classList.toggle('active',b.dataset.id===$('#loginid').value));}const form=$('#loginform'),idInput=$('#loginid'),passwordInput=$('#loginpassword');$('#togglepassword').onclick=()=>setPasswordVisibility(passwordInput,$('#togglepassword'),passwordInput.type==='password');const choice=()=>({rememberId:$('#rememberid').checked,rememberPassword:$('#rememberpassword').checked,id:idInput.value});$('#rememberid').onchange=$('#rememberpassword').onchange=()=>writeLoginPreferences(portal,choice());if(!demo&&preferences.rememberPassword)readBrowserPassword(idInput.value).then(credential=>{if(!credential||$('#loginform')!==form||passwordInput.value)return;if(!idInput.value)idInput.value=credential.id;passwordInput.value=credential.password;});form.onsubmit=e=>{e.preventDefault();action(async()=>{const options=choice(),password=passwordInput.value;try{actor=await store.login(portal==='admin'?'ADMIN':idInput.value.trim(),password);if(!allowsRole(portal,actor.role)){await store.logout();actor=null;throw Error('Use the correct app entry for your role.');}writeLoginPreferences(portal,{...options,id:actor.id});page=actor.role==='packer'?'confirmations':'overview';reviewRole='admin';reviewPacker='';menuOpen={};await load();if(!demo&&options.rememberPassword)saveBrowserPassword(actor.id,password).then(result=>{if(result.status!=='requested')toast('Signed in. Use your browser password manager to save this login.');});}catch(e){const target=$('#loginerror');if(target)target.innerHTML=`<div class="error">${esc(loginError(e))}</div>`;else toast(loginError(e));}});};}

function navItems(){return uiRole()==='admin'?[['overview','grid','Overview'],['outstanding','truck','Outstanding Collections'],['lossreview','alert','Damage & Loss'],['deliveries','truck','Deliveries'],['collections','box','Collections'],['confirmations','check','Approvals'],['payroll','wallet','Payroll'],['products','box','Products'],['people','users','People'],['issues','sync','Sync issues'],['deleted','clock','Deleted records'],['audit','clock','Audit log']]:uiRole()==='driver'?[['overview','grid','Overview'],['deliveries','truck','Outstanding'],['collections','box','Collections'],['losses','alert','Damage & Loss'],['sync','sync','Sync queue']]:[['deliveries','truck','Outstanding'],['confirmations','check','To confirm'],['payroll','wallet','My earnings'],['history','clock','History']];}
