function packerOptions(){return s.users.filter(u=>u.role==='packer'&&u.active).map(u=>`<option value="${esc(u.id)}">${esc(personLabel(u,'short'))} · ${esc(u.id)}</option>`).join('');}
async function orderForm(type){
 if(openingOrder)return;openingOrder=true;
 const delivery=type==='deliver',draftKey=`draft-${actor.id}-${type}`;
 let saved;
 try{await orderWriters.get(draftKey)?.flush().catch(()=>{});saved=reviewing()?null:await store.get(draftKey);}finally{openingOrder=false;}
 if(!actor)return;
 let draft=Array.isArray(saved?.draft)?saved.draft:[],packer=saved?.packer||s.users.find(u=>u.role==='packer'&&u.active)?.id||'',matched=null,submitted=false;
 const initial=saved?.inputs||{};
 const {el,onClose}=modal(delivery?'New delivery':'New collection',`<div class="field"><label for="opacker">PACKER</label><select id="opacker"><option value="">Choose a packer</option>${packerOptions()}</select></div><div id="orderentry"></div><div id="draft"></div><div id="allocation"></div><p id="draftstatus" role="status" class="muted">${saved?'Draft restored. Review the quantities before submitting.':'Your draft is saved automatically on this device.'}</p><div class="notice">${icon('clock')}<span>Submission locks this record. Only administration can correct it. Use × to close; background taps do not dismiss this form.</span></div>`,`<button class="btn" id="savedraft">Save draft</button><button class="btn primary" id="submitorder">Submit ${delivery?'delivery':'collection'}</button>`,{persistent:true});
 let stopCamera=()=>{};
 const writer=draftWriter(value=>store.put(draftKey,value));orderWriters.set(draftKey,writer);
 const capture=()=>({packer,draft,inputs:Object.fromEntries(['barcode','productsearch','addctn','collectproduct','collectctn','collectloose'].map(id=>[id,$('#'+id,el)?.value||''])),matchedId:matched?.id||'',updatedAt:new Date().toISOString()});
 const persist=()=>{if(reviewing()||submitted)return Promise.resolve();return writer.write(capture()).catch(()=>{if(document.body.contains(el))$('#draftstatus',el).textContent='Draft could not be saved. Keep this window open and try Save draft.';});};
 onClose(()=>{persist();stopCamera();});
 const preview=()=>{
  if(delivery){$('#allocation').innerHTML=draft.map(i=>{const p=s.products.find(p=>p.id===i.productId);try{return p?`<div class="notice">${esc(p.code)}: ${conversionText(p,i.ctn)}</div>`:'';}catch(e){return `<div class="error">${esc(e.message)}</div>`;}}).join('');return;}
  try{const state=clone(s);$('#allocation').innerHTML=draft.map(i=>{const t=state.tasks.find(t=>t.productId===i.productId&&t.packerId===packer);if(!t)throw Error('A draft product is no longer available. Remove it and refresh.');const pcs=linePcs(t,i.ctn,i.loose),a=allocate(state,packer,i.productId,pcs);return `<div class="notice"><span><strong>${esc(t.productCode)} · ${i.ctn} Ninso CTN + ${i.loose} loose = ${pcs} finished PCS</strong><br>${a.map(x=>`${short(x.task.occurredAt)} task → ${x.pcs} PCS`).join('<br>')}<br><small>Allocation is checked against the latest balance on upload.</small></span></div>`;}).join('');}catch(e){$('#allocation').innerHTML=`<div class="error">${esc(e.message)}</div>`;}
 };
 const drawDraft=()=>{
  $('#draft').innerHTML=draft.length?`<h3>Submission · ${draft.length} product(s)</h3>${draft.map((i,n)=>{const p=s.products.find(p=>p.id===i.productId)||s.tasks.find(t=>t.productId===i.productId)||{};return `<div class="draftline"><div><strong>${esc(p.code||p.productCode||i.productId)}</strong><small>${esc(p.name||p.productName||'Unavailable product')}</small></div><label>${delivery?'SUPPLIER':'NINSO'} CTN<br><input aria-label="Cartons" data-draftqty="${n}" type="number" min="${delivery?1:0}" step="1" value="${i.ctn}"></label>${delivery?'':`<label>LOOSE PCS<br><input aria-label="Loose pieces" data-draftloose="${n}" type="number" min="0" step="1" value="${i.loose}"></label>`}<button data-remove="${n}" aria-label="Remove product">×</button></div>`;}).join('')}`:'<p class="muted" style="text-align:center;padding:12px">No products added yet.</p>';
  $$('[data-remove]',el).forEach(b=>b.onclick=()=>{draft.splice(Number(b.dataset.remove),1);drawDraft();persist();});
  $$('[data-draftqty]',el).forEach(b=>b.oninput=b.onchange=()=>{draft[b.dataset.draftqty].ctn=Number(b.value);preview();persist();});
  $$('[data-draftloose]',el).forEach(b=>b.oninput=b.onchange=()=>{draft[b.dataset.draftloose].loose=Number(b.value);preview();persist();});preview();
 };
 function updateDelivery(){if(!$('#deliveryconversion'))return;try{$('#deliveryconversion').textContent=conversionText(matched,Number($('#addctn').value));}catch(e){$('#deliveryconversion').textContent=e.message;}}
 function updateCollection(){const box=$('#collectionconversion');if(!box)return;const t=s.tasks.find(t=>t.productId===$('#collectproduct').value&&t.packerId===packer);if(!t){box.textContent='Choose an unfinished product. Collection uses Ninso CTN, not Supplier CTN.';return;}const outstanding=s.tasks.filter(x=>x.productId===t.productId&&x.packerId===packer).reduce((n,x)=>n+remaining(s,x),0);let text='Outstanding: '+balanceText(outstanding,t)+' ('+fmt(outstanding)+' finished PCS). ';try{text+='This collection: '+fmt(linePcs(t,Number($('#collectctn').value),Number($('#collectloose').value)))+' finished PCS.';}catch{text+='Enter Ninso CTN and loose finished PCS to collect.';}box.textContent=text;}
 function chooseProduct(p){
  matched=p;
  $('#matched').innerHTML=`<div class="notice" style="margin-top:15px"><span><strong>${esc(p.code)}</strong><br>${esc(p.name)}<br><small>${esc(p.barcode||'Barcode missing')} · Supplier: ${p.supplierSize} EA / Supplier CTN · RP ${p.rpUnit}</small></span></div>${p.barcode?'':'<div class="error">Administration must add this product’s barcode before it can be delivered.</div>'}${field('SUPPLIER CTN','addctn',1,'number','min="1" step="1"')}<div id="deliveryconversion" class="notice" aria-live="polite"></div><button class="btn lime" id="adddelivery" ${p.barcode?'':'disabled'}>Add product</button>`;
  $('#addctn').oninput=()=>{updateDelivery();persist();};updateDelivery();
  $('#adddelivery').onclick=()=>action(async()=>{
   const ctn=Number($('#addctn').value);if(!p.barcode)throw Error('Product barcode is missing.');if(!Number.isSafeInteger(ctn)||ctn<1)throw Error('Enter a positive whole carton quantity.');
   const old=draft.find(i=>i.productId===p.id);if(old)old.ctn+=ctn;else draft.push({productId:p.id,ctn});matched=null;$('#barcode').value='';$('#productsearch').value='';$('#productresults').innerHTML='';$('#matched').innerHTML='';drawDraft();await persist();$('#productsearch').focus();
  });
 }
 function search(){
  const q=$('#productsearch').value,result=searchProducts(s.products,q,10);
  $('#productresults').innerHTML=!q.trim()?'':`<small>${result.total} match(es)${result.total>10?' · Showing 10. Add keywords to narrow results.':''}</small><div class="product-search-results">${result.items.map(p=>`<button type="button" data-searchproduct="${esc(p.id)}"><strong>${esc(p.name)}</strong><small>${esc(p.code)} · ${esc(p.barcode||'Barcode missing')}</small></button>`).join('')||'<p>No matching active products.</p>'}</div>`;
  $$('[data-searchproduct]',el).forEach(b=>b.onclick=()=>{const p=s.products.find(p=>p.id===b.dataset.searchproduct);if(p){chooseProduct(p);persist();}});
 }
 function find(){const p=s.products.find(p=>p.active&&p.barcode===$('#barcode').value.trim());if(!p){$('#matched').innerHTML='<div class="error">Barcode not found. Contact administration.</div>';return;}chooseProduct(p);persist();}
 const draw=()=>{
  $('#opacker').value=packer;
  $('#orderentry').innerHTML=delivery?`<div class="scanbox"><div class="field"><label for="productsearch">SEARCH PRODUCT NAME OR CODE</label><input id="productsearch" type="search" autocomplete="off" placeholder="e.g. LUX SOAP or 70G"></div><div id="productresults" aria-live="polite"></div><div class="field"><label for="barcode">SCAN OR ENTER PRODUCT BARCODE</label><input id="barcode" inputmode="numeric" placeholder="e.g. 9556860722138" autocomplete="off"></div><div class="actions"><button class="btn" id="camera">${icon('scan')}Open camera</button><button class="btn primary" id="findbarcode">Find barcode</button></div><div id="cameraarea"></div><div id="matched"></div></div>`:`<div class="scanbox"><div class="field"><label for="collectproduct">UNFINISHED PRODUCT</label><select id="collectproduct"><option value="">Choose from open tasks</option>${[...new Set(s.tasks.filter(t=>t.packerId===packer&&remaining(s,t)>=1).map(t=>t.productId))].map(id=>{const t=s.tasks.find(t=>t.packerId===packer&&t.productId===id);return `<option value="${esc(id)}">${esc(t.productCode)} · ${esc(t.productName)}</option>`;}).join('')}</select></div><div class="formgrid">${field('TOTAL CTN (NINSO) TO COLLECT','collectctn',0,'number','min="0" step="1"')}${field('LOOSE FINISHED PCS','collectloose',0,'number','min="0" step="1"')}</div><div id="collectionconversion" class="notice" aria-live="polite"></div><button class="btn" id="addcollection">${icon('plus')}Add to collection</button></div>`;
  drawDraft();
  if(delivery){$('#findbarcode').onclick=find;$('#barcode').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();find();}};$('#barcode').oninput=()=>persist();$('#productsearch').oninput=()=>{search();persist();};$('#camera').onclick=camera;}
  else{for(const id of ['collectproduct','collectctn','collectloose']){$('#'+id).oninput=$('#'+id).onchange=()=>{updateCollection();persist();};}$('#addcollection').onclick=()=>action(async()=>{const id=$('#collectproduct').value,t=s.tasks.find(t=>t.productId===id&&t.packerId===packer);if(!t)throw Error('Choose a product.');const ctn=Number($('#collectctn').value),loose=Number($('#collectloose').value);linePcs(t,ctn,loose);if(draft.some(i=>i.productId===id))throw Error('Product already added. Edit its quantity below.');draft.push({productId:id,ctn,loose});$('#collectctn').value='0';$('#collectloose').value='0';drawDraft();updateCollection();await persist();});updateCollection();}
 };
 async function camera(){await action(async()=>{stopCamera();if(!('BarcodeDetector'in window))throw Error('Camera barcode scanning is unavailable in this browser. Use Chrome on Android or enter barcode digits.');const formats=await BarcodeDetector.getSupportedFormats();const detector=new BarcodeDetector({formats:formats.filter(x=>['ean_13','ean_8','code_128','upc_a','upc_e','code_39','itf'].includes(x))});const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});let running=true;$('#cameraarea').innerHTML='<video id="scanvideo" playsinline muted></video><button class="btn small" id="stopcamera">Stop camera</button>';const video=$('#scanvideo');video.srcObject=stream;stopCamera=()=>{running=false;stream.getTracks().forEach(t=>t.stop());$('#cameraarea')?.replaceChildren();};$('#stopcamera').onclick=stopCamera;await video.play();const scan=async()=>{if(!running)return;try{const codes=await detector.detect(video);if(codes.length){$('#barcode').value=codes[0].rawValue;stopCamera();find();return;}}catch{}if(running)setTimeout(scan,220);};scan();});}
 $('#opacker').onchange=e=>{packer=e.target.value;draft=[];matched=null;stopCamera();draw();persist();};
 $('#savedraft').onclick=()=>action(async()=>{await persist();await writer.flush();modalClose();toast('Draft saved on this device');});
 $('#submitorder').onclick=()=>action(async()=>{
  if(submitted)return;if(!packer||!draft.length)throw Error('Select a packer and add products.');
  for(const i of draft){if(delivery&&(!Number.isSafeInteger(i.ctn)||i.ctn<1))throw Error('CTN must be a positive integer.');if(!delivery){const task=s.tasks.find(t=>t.productId===i.productId&&t.packerId===packer);if(!task)throw Error('Task no longer available. Refresh and review the draft.');linePcs(task,i.ctn,i.loose);}}
  await writer.flush();await send(type,{packerId:packer,items:draft,occurredAt:new Date().toISOString()});submitted=true;$('#submitorder').disabled=true;await writer.write(null);modalClose();await load();toast('Submitted. Check the sync queue for upload status.');
 });
 if(reviewing()){$('#submitorder').disabled=true;$('#savedraft').disabled=true;}
 draw();
 if(delivery&&saved?.matchedId){const p=s.products.find(p=>p.id===saved.matchedId&&p.active);if(p)chooseProduct(p);}
 for(const [id,value] of Object.entries(initial)){const input=$('#'+id,el);if(input)input.value=value;}
 if(delivery&&initial.productsearch)search();if(delivery)updateDelivery();else updateCollection();
 el.addEventListener('input',()=>persist());el.addEventListener('change',()=>persist());
 if(!reviewing())await persist();
}

function confirmItem(id){const r=s.returns.find(r=>r.id===id);modal('Confirm collection',`<p>You are confirming <strong>${fmt(r.pcs)} finished PCS</strong> of ${esc(r.productName)} at <strong>${rate(r.rateMicros)} / PCS</strong>.</p><div class="notice">Total earnings: <strong>${money(r.amountCents)}</strong></div><p class="muted">This item will be locked and moved to History. Changes require administration.</p>`,`<button class="btn primary" id="yesconfirm">Confirm quantity & earnings</button>`);$('#yesconfirm').onclick=()=>action(async()=>{await mutate('confirm',{id,version:r.version});modalClose();toast('Confirmed and locked');});}
function dispute(id){const r=s.returns.find(r=>r.id===id);modal('Report an issue',`<p>${esc(r.productName)}</p><div class="field"><label for="reason">WHAT NEEDS CORRECTING?</label><textarea id="reason" placeholder="Describe the quantity or amount discrepancy"></textarea></div>`,`<button class="btn primary" id="sendissue">Submit issue</button>`);$('#sendissue').onclick=()=>action(async()=>{await mutate('dispute',{id,version:r.version,note:$('#reason').value});modalClose();toast('Issue sent for administration review');});}
function correctReturn(id){const r=s.returns.find(r=>r.id===id),settled=!!r.settlementId;modal(settled?'Create payroll adjustment':'Correct collection',`<p>${esc(r.productName)} · ${esc(name(r.packerId))}</p>${settled?'<div class="notice warn">The closed statement stays unchanged. This creates a separate adjustment for packer confirmation.</div>':''}<div class="formgrid">${field('CORRECT FINISHED PCS','correctpcs',r.pcs,'number','min="0" step="1"')}${field('CORRECT RATE / PCS','correctrate',rate(r.rateMicros),'number','min="0" step="0.000001"')}</div><div class="field"><label for="reason">CORRECTION REASON</label><textarea id="reason"></textarea></div>`,`<button class="btn primary" id="savecorrection">${settled?'Create adjustment':'Save & request confirmation'}</button>`);$('#savecorrection').onclick=()=>action(async()=>{const pcs=Number($('#correctpcs').value),micros=Math.round(Number($('#correctrate').value)*1e6),note=$('#reason').value;await mutate(settled?'adjustment':'correctReturn',settled?{id,newPcs:pcs,newRateMicros:micros,note}:{id,pcs,rateMicros:micros,note});modalClose();toast('Correction saved for packer confirmation');});}
function correctTask(id){const t=s.tasks.find(t=>t.id===id);modal('Correct delivery',`<p>${esc(t.productName)} · ${esc(name(t.packerId))}</p>${field('CORRECT SUPPLIER CTN','taskctn',t.ctn,'number','min="1" step="1"')}<div class="field"><label for="reason">CORRECTION REASON</label><textarea id="reason"></textarea></div>`,`<button class="btn primary" id="savetask">Save correction</button>`);$('#savetask').onclick=()=>action(async()=>{await mutate('correctTask',{id,ctn:Number($('#taskctn').value),note:$('#reason').value});modalClose();toast('Delivery corrected; original values retained in audit log');});}
function lossForm(){modal('Report Damage & Loss',`<div class="field"><label for="ltask">DELIVERY TASK</label><select id="ltask"><option value="">Choose task</option>${openTasks(s).map(t=>`<option value="${esc(t.id)}">${esc(name(t.packerId))} · ${esc(t.productCode)} · ${short(t.occurredAt)} · ${fmt(taskSummary(s,t).reportableEA)} EA available to report</option>`).join('')}</select></div><div class="formgrid">${field('QUANTITY','lqty',1,'number','min="1" step="1"')}<div class="field"><label for="lunit">UNIT</label><select id="lunit"><option value="raw">Each (EA)</option><option value="finished">Finished PCS</option></select></div><div class="field"><label for="lreason">TYPE</label><select id="lreason"><option value="damaged">Damaged</option><option value="missing">Missing</option></select></div></div><div class="field"><p>Each (EA) counts one item before packing. Finished PCS counts one completed portion; RP Unit determines how many EA it contains.</p><label for="lnote">EXPLANATION</label><textarea id="lnote"></textarea></div>`,`<button class="btn primary" id="saveloss">Submit for admin review</button>`);$('#saveloss').onclick=()=>action(async()=>{const payload={taskId:$('#ltask').value,qty:Number($('#lqty').value),unit:$('#lunit').value,reason:$('#lreason').value,note:$('#lnote').value};validateLossReport(s,payload);await mutate('loss',payload);modalClose();toast('Exception submitted');});}
function reviewLoss(id){const l=s.losses.find(l=>l.id===id);modal('Review Damage & Loss',`<p><strong>${l.qty} ${lossUnitLabel(l.unit)} · ${esc(l.reason)} (${fmt(l.rawQty)} EA total)</strong></p><p>${esc(l.note)}</p><div class="field"><label for="reviewnote">ADMINISTRATION NOTE</label><textarea id="reviewnote"></textarea></div>`,`<button class="btn danger" id="rejectloss">Reject</button><button class="btn primary" id="approveloss">Approve loss</button>`);for(const [idb,approve] of [['rejectloss',false],['approveloss',true]])$('#'+idb).onclick=()=>action(async()=>{await mutate('reviewLoss',{id,approve,note:$('#reviewnote').value});modalClose();toast('Exception reviewed');});}
function productForm(p){const old=p;p=p||{id:uid(),code:'',name:'',barcode:'',supplierSize:1,rpUnit:1,ninsoSize:1,rateMicros:0,bag:'',active:true};modal(old?'Edit product':'Add product',`<div class="formgrid">${field('PRODUCT CODE','pcode',p.code)}${field('BARCODE (TEXT)','pbarcode',p.barcode)}<div class="wide">${field('DESCRIPTION','pname',p.name)}</div>${field('SUPPLIER CTN (REFERENCE)','preference',p.referenceCtn||1,'number','min="1" step="1"')}${field('EACH (EA) / SUPPLIER CTN','psupplier',p.supplierSize,'number','min="1" step="1"')}${field('EA / FINISHED PCS (RP UNIT)','prp',p.rpUnit,'number','min="1" step="1"')}${field('FINISHED PCS / NINSO CTN','pninso',p.ninsoSize,'number','min="1" step="1"')}${field('PACKING FEE / FINISHED PCS','prate',rate(p.rateMicros),'number','min="0" step="0.000001"')}${field('PACKING MATERIAL','pbag',p.bag)}${field('OUTER','pouter',p.outer||'')}<div class="field"><label for="pactive">STATUS</label><select id="pactive"><option value="true" ${p.active?'selected':''}>Active</option><option value="false" ${!p.active?'selected':''}>Inactive</option></select></div></div><div id="producttotals" class="notice" aria-live="polite"></div><small>Rate changes apply to new tasks. Existing task rates stay unchanged.</small>`,`<button class="btn primary" id="saveproduct">Save product</button>`);$('#saveproduct').onclick=()=>action(async()=>{await mutate('saveProduct',{id:p.id,code:$('#pcode').value.trim(),name:$('#pname').value.trim(),barcode:$('#pbarcode').value.trim(),supplierSize:Number($('#psupplier').value),rpUnit:Number($('#prp').value),ninsoSize:Number($('#pninso').value),rateMicros:Math.round(Number($('#prate').value)*1e6),bag:$('#pbag').value,outer:$('#pouter').value,referenceCtn:Number($('#preference').value),active:$('#pactive').value==='true'});modalClose();toast('Product saved');});const showTotals=()=>{try{const p={supplierSize:Number($('#psupplier').value),rpUnit:Number($('#prp').value),ninsoSize:Number($('#pninso').value)},t=packingTotals(p,Number($('#preference').value));$('#producttotals').textContent=`Supplier CTN × Supplier Size = ${fmt(t.totalSupplierPcs)} TOTAL PCS (Supplier). TOTAL PCS ÷ (RP Unit × PACKSIZE (Ninso)) = ${t.totalNinsoCtn.toLocaleString('en',{maximumFractionDigits:6})} TOTAL CTN (Ninso). Finished PCS = ${fmt(t.finishedPcs)}.`;}catch(e){$('#producttotals').textContent=e.message;}};for(const id of ['preference','psupplier','prp','pninso'])$('#'+id).oninput=showTotals;showTotals();}
function personForm(u){const old=u;u=u||{id:'',name:'',no:'',ic:'',role:'packer',extraMicros:0,active:true};modal(old?'Manage person':'Add person',`<div class="formgrid">${field('NO','uno',u.no||'')}${field('ID','uid',u.id,'text',old?'readonly':'')}${field('NAME','uname',u.name)}${field('Short Name','ushort',u.shortName||'')}${field('IC','uic',u.ic||'')}<div class="field"><label>Password</label><input value="${u.authUid?'Set — not viewable':'Login not created'}" readonly></div><div class="field"><label for="urole">Role</label><select id="urole" ${old?'disabled':''}>${['packer','driver','admin'].map(r=>`<option value="${r}" ${u.role===r?'selected':''}>${roleLabel(r)}</option>`).join('')}</select></div>${field('Additional Pay / PCS','uextra',rate(u.extraMicros),'number','min="0" step="0.000001"')}<div class="field"><label for="uactive">Status</label><select id="uactive"><option value="true" ${u.active?'selected':''}>Active</option><option value="false" ${u.active?'':'selected'}>Inactive</option></select></div></div><div class="notice">IC is visible to administration only. Passwords cannot be viewed. Create / link login establishes the Firebase login for this saved person. Existing passwords are never changed here.</div>${old?'<button class="btn" id="provisionlogin">Create / link login</button> <button class="btn danger" id="requestreset">Request password reset</button><div id="resetstatus"></div>':''}`,'<button class="btn primary" id="saveperson">Save person</button>');if(old)$('#provisionlogin').onclick=()=>loginAccountForm(u);if(old)$('#requestreset').onclick=()=>action(async()=>{await store.accountAction({action:'reset',id:u.id});$('#resetstatus').innerHTML='<div class="notice">Reset requested. Process it with the PC account manager.</div>';$('#requestreset').disabled=true;});$('#saveperson').onclick=()=>action(async()=>{const person={...u,id:$('#uid').value.trim(),no:$('#uno').value.trim(),name:$('#uname').value.trim(),shortName:$('#ushort').value.trim(),ic:$('#uic').value.trim(),role:$('#urole').value,extraMicros:Math.round(Number($('#uextra').value)*1e6),active:$('#uactive').value==='true'};await store.accountAction({action:'save',person});await store.refresh(actor);modalClose();await load();toast('Person saved');});}
function closeMonth(){const pending=s.returns.filter(r=>r.serviceMonth===month&&r.status!=='confirmed').length;modal('Close monthly payroll',`${field('PAYROLL MONTH','closingmonth',month,'month')}<div class="notice warn">Only confirmed items are included. Late confirmations from closed service months are carried into a later payroll.</div><p>Selected month has <strong>${pending}</strong> unconfirmed item(s). Before the confirmation deadline, all items must be confirmed to close early.</p><p class="muted">The closed statement is immutable. Later corrections use separate adjustments.</p>`,`<button class="btn primary" id="finalclose">Close & lock payroll</button>`);$('#finalclose').onclick=()=>action(async()=>{await mutate('settle',{month:$('#closingmonth').value});modalClose();toast('Payroll closed. Download the statement below.');});}
function download(filename,text,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(rows){return '\ufeff'+rows.map(row=>row.map(x=>{let v=String(x??'');if(/^[=+@\-]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"';}).join(',')).join('\r\n');}
function exportReturns(){const rows=page==='payroll'?filtered(s.returns.filter(r=>inDateRange(r.occurredAt,selectedRange()))):filtered(s.returns);const head=['Collection ID','Task ID','Collection date (Singapore)','Service month','Packer ID','Packer','Logistics ID','Product code','Product','Ninso CTN','Loose finished PCS','Total finished PCS','Rate / PCS','Amount','Status','Confirmed at','Settlement ID'];download(`packflow-collections-${month}.csv`,csv([head,...rows.map(r=>[r.collectionId,r.taskId,new Date(r.occurredAt).toLocaleString('en-GB',{timeZone:'Asia/Singapore'}),r.serviceMonth,r.packerId,name(r.packerId),r.driverId,r.productCode,r.productName,Math.floor(r.pcs/r.ninsoSize),r.pcs%r.ninsoSize,r.pcs,rate(r.rateMicros),money(r.amountCents),r.status,r.confirmedAt||'',r.settlementId||''])]));}
function statement(id){const z=s.settlements.find(z=>z.id===id);download(`packflow-payroll-${z.month}.csv`,csv([['Payroll month','Packer ID','Packer','Product code','Product','Service month','PCS','Rate / PCS','Amount','Supplement','Adjustment'],...z.lines.map(l=>[z.month,l.packerId,name(l.packerId),l.productCode,l.productName,l.serviceMonth,l.pcs,rate(l.rateMicros),money(l.amountCents),l.supplement?'Yes':'No',l.adjustment?'Yes':'No'])]));}
function importForm(type){
 if(type==='people')return peopleImportForm();
 let staged=[],completed=0,uploading=false,complete=false;
 const popup=modal('Import product catalogue',`<p>Upload a UTF-8 CSV. IDs and barcodes remain text.</p><div class="notice">${PRODUCT_HEADERS.join(' · ')}</div><button class="btn small" id="template">Download CSV template</button><div class="field"><label for="importfile">CSV FILE</label><input id="importfile" type="file" accept=".csv,text/csv"></div><div id="importpreview"></div><div id="importstatus" role="status" aria-live="polite"></div><div class="notice warn">PACKING FEE is per finished PCS. TOTAL fields are checked against pack sizes.</div>`,'<button class="btn primary" id="commitimport" disabled>Import products</button><button class="btn" id="closeimport">Close</button>');
 const close=modalClose;modalClose=()=>{if(!uploading)close();};
 const progress=({completed:done,total,state,error})=>{$('#importstatus').innerHTML=`<div class="import-result ${state==='failed'?'failed':state==='complete'?'success':''}"><strong>${state==='complete'?'Import complete':state==='failed'?'Import stopped':'Uploading…'}</strong><p>${done} / ${total} records saved${state==='saving'?' · please keep this window open':''}.</p><progress value="${done}" max="${total}" aria-label="Import progress"></progress>${error?`<p>${esc(error)}</p><small>Retry continues with the remaining records. Saved records will not be repeated.</small>`:''}</div>`;};
 $('#closeimport').onclick=()=>modalClose();$('#template').onclick=()=>download('packflow-products-template.csv',csv([PRODUCT_HEADERS,productSample]));
 $('#importfile').onchange=()=>action(async()=>{
  $('#commitimport').disabled=true;$('#commitimport').textContent='Import products';staged=[];completed=0;complete=false;$('#importstatus').innerHTML='';$('#modalerror').innerHTML='';
  const file=$('#importfile').files[0];if(!file)return;
  const objects=objectsFromCSV(await file.text()),ids=new Set();
  staged=objects.map((o,i)=>{try{const x=mapProduct(o,s.products.find(p=>p.code===String(o.Code||o.code||'').trim()),uid());if(ids.has(x.code))throw Error('Duplicate ID/code in file.');ids.add(x.code);return x;}catch(e){throw Error(`Row ${i+2}: ${e.message}`);}});
  let state=clone(s);for(const x of staged)state=execute(state,{id:uid(),type:'saveProduct',payload:x},actor);
  $('#importpreview').innerHTML=`<strong>${staged.length} valid record(s), ready to import</strong><div class="importpreview"><table><tbody>${staged.slice(0,10).map(x=>`<tr><td>${esc(x.code)}</td><td>${esc(x.name)}</td><td>${rate(x.rateMicros)}</td></tr>`).join('')}</tbody></table></div>`;$('#commitimport').disabled=false;
 });
 $('#commitimport').onclick=()=>action(async()=>{
  if(uploading||complete||!staged.length)return;
  const button=$('#commitimport');uploading=true;button.disabled=true;$('#importfile').disabled=true;$('#closeimport').disabled=true;$('.close',popup.el).disabled=true;button.textContent='Uploading…';
  try{
   await importRows(staged,x=>store.send(actor,'saveProduct',x,{deferRefresh:true}),p=>{completed=p.completed;progress(p);},completed);
   complete=true;lastImportResult={type:'products',count:completed};let refreshError='';
   try{await store.refresh(actor);query='';productPage=1;await load();}catch(e){refreshError=e.message;}
   progress({completed,total:staged.length,state:'complete'});$('#importpreview').innerHTML='';
   if(refreshError)$('#importstatus').insertAdjacentHTML('beforeend',`<div class="notice warn">Records were saved, but the list could not refresh: ${esc(refreshError)}. Use Refresh after closing this window.</div>`);
   button.textContent='Import complete';toast(`Successfully imported ${completed} records`);
  }catch(e){progress({completed,total:staged.length,state:'failed',error:e.message});button.textContent=`Retry remaining (${staged.length-completed})`;try{await store.refresh(actor);await load();}catch{}}
  finally{uploading=false;button.disabled=complete;$('#importfile').disabled=false;$('#closeimport').disabled=false;$('.close',popup.el).disabled=false;}
 });
}
window.addEventListener('online',()=>{if(actor)action(async()=>{await store.sync(actor);await store.refresh(actor);await load({background:true});});});window.addEventListener('offline',()=>{if(actor)load({background:true});});
try{await store.init();actor=await store.get('session');if(actor&&!allowsRole(portal,actor.role))actor=null;if(actor){page=actor.role==='packer'?'confirmations':'overview';if(navigator.onLine){try{await store.sync(actor);await store.refresh(actor);}catch(e){toast('Using saved data: '+e.message);}}await load();}else loginView();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(e=>toast('Offline cache unavailable: '+e.message));}catch(e){$('#app').innerHTML=`<div class="panel" style="margin:10% auto;max-width:500px;padding:30px"><h1>Workspace unavailable</h1><p>${esc(e.message)}</p><p>Open in a regular Chrome window with local storage enabled.</p></div>`;}

function resolveSyncForm(id){const q=s.syncErrors.find(x=>x.id===id);const payload=clone(q.cmd.payload);const isLoss=q.cmd.type==='loss';modal('Resolve driver submission',`<p>${esc(q.error)}</p>${!isLoss?`<div class="field"><label for="issuepacker">PACKER</label><select id="issuepacker">${packerOptions()}</select></div>${payload.items.map((i,n)=>{const p=s.products.find(p=>p.id===i.productId);return `<div class="notice"><strong>${esc(p?.code||i.productId)}</strong></div><div class="formgrid">${field('CTN',`issuectn${n}`,i.ctn,'number','min="0" step="1"')}${q.cmd.type==='receive'?field('LOOSE PCS',`issueloose${n}`,i.loose,'number','min="0" step="1"'):''}</div>`;}).join('')}`:`${field('QUANTITY','issueqty',payload.qty,'number','min="1" step="1"')}`}<div class="field"><label for="issuenote">ADMINISTRATION REASON</label><textarea id="issuenote"></textarea></div><p class="muted">The original submission is retained. The device clears its locked queue item after the next successful sync.</p>`,`<button class="btn danger" id="rejectissue">Reject submission</button><button class="btn primary" id="correctissue">Correct & accept</button>`);if(!isLoss)$('#issuepacker').value=payload.packerId;for(const [button,reject] of [['rejectissue',true],['correctissue',false]])$('#'+button).onclick=()=>action(async()=>{if(!isLoss){payload.packerId=$('#issuepacker').value;payload.items.forEach((i,n)=>{i.ctn=Number($('#issuectn'+n).value);if(q.cmd.type==='receive')i.loose=Number($('#issueloose'+n).value);});}else payload.qty=Number($('#issueqty').value);await store.resolveIssue({id,payload,reject,note:$('#issuenote').value});await store.refresh(actor);modalClose();await load();toast('Submission resolved');});}

function mobileHome(){const open=openTasks(s);return heading('Ready for the next stop?','Deliver cartons. Collect finished pieces.')+`<div class="phone-actions"><button id="newdelivery" class="phone-action primary">${icon('scan')}<strong>New delivery</strong><small>Scan product barcode</small></button><button id="newcollection" class="phone-action">${icon('box')}<strong>Collect goods</strong><small>CTN + loose PCS</small></button></div><div class="stats">${stat('Open tasks',open.length,'Awaiting collection or EA loss review','truck')}<button class="btn" id="gooutstanding">Outstanding Collections</button>${stat('Pending uploads',queue.length,'Saved on this phone','sync')}</div>${queue.length?'<div class="notice warn"><span>Upload pending. Keep your phone data until synced.</span><button class="btn small" id="goqueue">View</button></div>':''}<h2>Recent collections</h2>${mobileReceipts([...s.returns].sort((a,b)=>b.occurredAt.localeCompare(a.occurredAt)).slice(0,5))}`;}
function mobileReceipts(rows){return rows.length?rows.map(r=>`<article class="phone-record"><div class="row"><span class="mono">${esc(r.productCode)}</span>${badge(r.status)}</div><h3>${esc(r.productName)}</h3><div class="row"><small>${actor.role==='driver'?esc(name(r.packerId))+' · ':''}${short(r.occurredAt)}</small><strong>${fmt(r.pcs)} PCS</strong></div><div class="row"><small>${Math.floor(r.pcs/r.ninsoSize)} CTN + ${r.pcs%r.ninsoSize} loose</small>${actor.role==='packer'?`<strong>${money(r.amountCents)}</strong>`:''}</div></article>`).join(''):empty('No collections yet','Your collected products will appear here.');}
function mobileTasks(rows){return rows.length?rows.map(t=>`<article class="phone-record"><div class="row"><span class="mono">${esc(t.productCode)}</span>${badge(remaining(s,t)*t.rpUnit<=1e-7?'closed':'open')}</div><h3>${esc(t.productName)}</h3><div class="row"><small>${esc(name(t.packerId))} · ${short(t.occurredAt)}</small><strong>${t.ctn} supplier CTN</strong></div><div class="phone-balance"><span>Outstanding collection</span><strong>${balanceText(remaining(s,t),t)}</strong></div><small>Collected: ${balanceText(taskSummary(s,t).received,t)} · Approved Damage & Loss: ${fmt(taskSummary(s,t).approvedEA)} EA</small><br><small>Expected collection: ${balanceText(t.expected,t)} · ${fmt(t.expected)} finished PCS</small><br><small>Supplier ${t.supplierSize} EA / Supplier CTN · RP ${t.rpUnit} · Ninso ${t.ninsoSize} PCS / CTN</small></article>`).join(''):empty('No open tasks','Deliveries will appear here.');}

function reviewState(state){
 if(actor?.role==='admin'&&reviewRole==='packer'&&!state.users.some(u=>u.id===reviewPacker&&u.role==='packer'))reviewPacker=state.users.find(u=>u.role==='packer')?.id||'';
 const view=clone(reviewSnapshot(state,actor,reviewRole,reviewPacker));view.tasks=view.tasks.filter(liveRecord);view.returns=view.returns.filter(liveRecord);return view;
}
function renderReviewControls(){
 if(actor.role!=='admin')return;
 const bar=document.createElement('section');bar.className='admin-review-bar';
 bar.innerHTML=`<strong>ADMIN · ${esc(actor.name)}</strong><label>View <select id="adminview" aria-label="Admin view"><option value="admin" ${reviewRole==='admin'?'selected':''}>Administration</option><option value="driver" ${reviewRole==='driver'?'selected':''}>Logistics</option><option value="packer" ${reviewRole==='packer'?'selected':''}>Packer</option></select></label>${reviewRole==='packer'?`<label>Packer <select id="reviewpacker" aria-label="Review packer">${fullState.users.filter(u=>u.role==='packer').map(u=>`<option value="${esc(u.id)}" ${u.id===reviewPacker?'selected':''}>${esc(personLabel(u,'combined'))} · ${esc(u.id)}</option>`).join('')||'<option value="">No packers available</option>'}</select></label>`:''}${reviewing()?'<span>READ-ONLY REVIEW · Use Administration to change records. Packer confirmations stay with the packer.</span>':'<span>Full administrative access</span>'}`;
 $('#app').prepend(bar);
 $('#adminview').onchange=async e=>{reviewRole=e.target.value;page=reviewRole==='packer'?'confirmations':'overview';query='';statusFilter='all';s=reviewState(fullState);render();};
 if($('#reviewpacker'))$('#reviewpacker').onchange=e=>{reviewPacker=e.target.value;s=reviewState(fullState);render();};
}
function lockReviewActions(){
 if(!reviewing())return;
 for(const button of $$('[data-confirm],[data-dispute],[data-adjconfirm],#newloss')){button.disabled=true;button.title='Read-only Admin review';}
}
function loginAccountForm(person){
 if(actor.role!=='admin')return;
 modal('Create / link login',`<p><strong>${esc(person.name)}</strong> · ${esc(person.id)} · ${esc(roleLabel(person.role))}</p><p>Firebase login: <strong>${esc(person.id.toLowerCase())}@packflow-a69bb.invalid</strong></p><div class="notice">For a new login, enter its initial password. If it already exists, enter its current password to verify and link it. Existing passwords are not changed. Your administrator session remains signed in.</div>${field('LOGIN PASSWORD','provisionpassword','','password','autocomplete="new-password" minlength="6" required')}<p>Password is sent only to Firebase Authentication and is not saved in personnel data.</p>`,'<button class="btn primary" id="createaccount">Create / link login</button>');
 $('#createaccount').onclick=()=>action(async()=>{
 const button=$('#createaccount');button.disabled=true;
 try{const result=await store.provisionAccount(person.id,$('#provisionpassword').value);$('#provisionpassword').value='';await store.refresh(actor);modalClose();await load();toast(result.created?'Login created and linked.':'Existing login verified and linked.');}
 catch(e){button.disabled=false;throw Error(loginError(e));}
 });
}
function peopleImportForm(){
 if(actor.role!=='admin'||reviewing())return;
 let rows=[],running=false;
 const popup=modal('Import people & logins',`<p>One CSV imports personnel details and creates their login accounts. Use the existing personnel template including ID and Password.</p><div class="notice">New logins use the CSV password. Already linked logins keep their current password. Existing unlinked logins are verified with their current password before linking; passwords are never reset by import.</div><button class="btn small" id="peopletemplate">Download CSV template</button><div class="field"><label for="peopleimportfile">PERSONNEL CSV</label><input id="peopleimportfile" type="file" accept=".csv,text/csv"></div><div id="peopleimportstatus" role="status" aria-live="polite"></div><div id="peopleimportresults"></div><p>Complete means both personnel data and login setup succeeded. Passwords are kept in memory for pending rows only and are excluded from reports.</p>`,`<button class="btn" id="peoplereport" disabled>Download results</button><button class="btn primary" id="importpeopleall" disabled>Import people & logins</button><button class="btn" id="closepeopleimport">Close</button>`);
 popup.onClose(()=>{clearPeopleImport(rows);rows=[];});
 const close=modalClose;modalClose=()=>{if(!running)close();};
 const summary=()=>Object.fromEntries(['complete','failed','invalid','inactive'].map(status=>[status,rows.filter(r=>r.status===status).length]));
 const paint=()=>{
  const report=peopleImportReport(rows),n=summary(),processed=report.filter(r=>!['ready','processing'].includes(r.status)).length;
  $('#peopleimportstatus').innerHTML=`<div class="notice"><span><strong>${running?'Importing personnel and logins…':'Import results'}</strong><br>${n.complete} complete · ${n.failed} failed · ${n.invalid} invalid · ${n.inactive} inactive<br>${processed} / ${rows.length} processed</span></div><progress value="${processed}" max="${Math.max(1,rows.length)}" aria-label="Personnel and login import progress"></progress>`;
  $('#peopleimportresults').innerHTML=`<div class="tablewrap"><table><thead><tr><th>Row</th><th>ID</th><th>Name</th><th>Personnel</th><th>Login</th><th>Status</th><th>Result</th></tr></thead><tbody>${report.map(r=>`<tr><td>${r.row}</td><td>${esc(r.id)}</td><td>${esc(r.name)}</td><td>${esc(r.profileStatus)}</td><td>${esc(r.loginStatus)}</td><td>${esc(r.status)}</td><td>${esc(r.message)}</td></tr>`).join('')}</tbody></table></div>`;
  $('#importpeopleall').disabled=running||!rows.some(r=>['ready','failed'].includes(r.status));
  $('#importpeopleall').textContent=running?'Importing…':n.failed?'Retry incomplete rows':'Import people & logins';
  $('#peoplereport').disabled=running||!rows.length;
 };
 $('#peopletemplate').onclick=()=>download('packflow-people-template.csv',csv([PEOPLE_HEADERS,personSample]));
 $('#closepeopleimport').onclick=()=>modalClose();
 $('#peoplereport').onclick=()=>download('packflow-personnel-import-results.csv',csv([['Row','ID','Name','Personnel','Login','Status','Result'],...peopleImportReport(rows).map(r=>[r.row,r.id,r.name,r.profileStatus,r.loginStatus,r.status,r.message])]));
 $('#peopleimportfile').onchange=()=>action(async()=>{
  clearPeopleImport(rows);rows=[];paint();$('#modalerror').textContent='';
  const file=$('#peopleimportfile').files[0];if(!file)return;
  rows=preparePeopleImport(await file.text(),fullState?.users||s.users,actor);paint();
 });
 $('#importpeopleall').onclick=()=>action(async()=>{
  if(running||!rows.some(r=>['ready','failed'].includes(r.status)))return;
  running=true;$('#peopleimportfile').disabled=true;$('#closepeopleimport').disabled=true;$('.close',popup.el).disabled=true;$('#modalerror').textContent='';paint();
  try{
   await runPeopleImport(rows,{save:person=>store.accountAction({action:'save',person}),login:(id,password,options)=>store.provisionAccount(id,password,options)},paint);
   lastImportResult={type:'people',...summary()};
   try{await store.refresh(actor);query='';await load();}catch{$('#modalerror').textContent='Row results are recorded, but the list could not refresh. Use Refresh after closing this dialog.';}
   const n=summary();toast(`Personnel import finished: ${n.complete} complete, ${n.failed} failed, ${n.invalid} invalid.`);
  }finally{running=false;$('#peopleimportfile').disabled=false;$('#closepeopleimport').disabled=false;$('.close',popup.el).disabled=false;paint();}
 });
}

function balanceText(pcs,p){const b=packingBalance(pcs,p);return fmt(b.ctn)+' Ninso CTN + '+fmt(b.loose)+' loose PCS'+(b.rawRemainder>1e-7?' + '+fmt(b.rawRemainder)+' EA remaining':'');}
function conversionText(p,ctn){const t=packingTotals(p,ctn);return fmt(ctn)+' Supplier CTN × '+fmt(p.supplierSize)+' = '+fmt(t.totalSupplierPcs)+' TOTAL PCS (Supplier); ÷ ('+p.rpUnit+' × '+p.ninsoSize+') = '+t.totalNinsoCtn.toLocaleString('en',{maximumFractionDigits:6})+' TOTAL CTN (Ninso) · '+fmt(t.finishedPcs)+' finished PCS.';}
function deleteRecordForm(type,id){
 if(actor.role!=='admin'||reviewing())return;
 const row=(type==='product'?s.products:type==='delivery'?s.tasks:s.returns).find(r=>r.id===id);if(!row)return;
 const used=type==='product'&&(fullState.tasks.some(t=>t.productId===id)||fullState.returns.some(r=>r.productId===id)||fullState.adjustments.some(a=>a.productId===id)||fullState.settlements.some(z=>z.lines.some(l=>l.productId===id||l.productCode===row.code)));
 const settled=type==='collection'&&!!row.settlementId;
 const message=type==='product'?(used?'This product has historical activity. It will be deactivated, preserving its records and salary history.':'This unused product will be permanently removed from the catalogue. Its deletion stays in the audit log.'):type==='delivery'?'This delivery will be voided and removed from available balances. Linked collections, pending adjustments and loss reports must be handled first.':settled?'The closed payroll statement will stay unchanged. A full negative quantity/amount adjustment will be created for the packer to confirm. Until confirmation, the quantity and payable adjustment remain unchanged.':'This collection will be voided. Its quantity returns to the original delivery balance and its amount is removed from unclosed payroll. The original record remains in Deleted records.';
 const label=settled?'Create reversal adjustment':used?'Deactivate product':'Confirm delete';
 modal(settled?'Reverse settled collection':'Delete '+type,`<p><strong>${esc(row.code||row.productCode||id)}</strong> · ${esc(row.name||row.productName||'')}</p><p class="mono">${esc(id)}</p><div class="notice warn">${esc(message)}</div><div class="field"><label for="deletereason">REASON (REQUIRED)</label><textarea id="deletereason"></textarea></div>`,'<button class="btn danger" id="confirmdelete">'+label+'</button>');
 $('#confirmdelete').onclick=()=>action(async()=>{
  const note=$('#deletereason').value.trim();if(!note)throw Error('Enter a deletion reason.');
  try{await mutate(type==='product'?'deleteProduct':type==='delivery'?'voidTask':settled?'adjustment':'voidReturn',settled?{id,newPcs:0,newRateMicros:row.rateMicros,note}:{id,note});}
  catch(e){if(type==='product'&&!used&&String(e.code).includes('permission-denied'))throw Error('Publish the v0.15 firestore.rules file in Firebase before permanently deleting an unused product.');throw e;}
  modalClose();toast(settled?'Reversal created. Awaiting packer confirmation.':used?'Product deactivated.':type==='product'?'Product deleted.':'Record voided; balances updated.');
 });
}
function deletedRecords(){
 const records=[...fullState.tasks.filter(r=>!liveRecord(r)).map(r=>({...r,kind:'Delivery'})),...fullState.returns.filter(r=>!liveRecord(r)).map(r=>({...r,kind:'Collection'}))].sort((a,b)=>(b.voidedAt||'').localeCompare(a.voidedAt||''));
 return records.length?`<div class="tablewrap"><table><thead><tr><th>Type / reference</th><th>Product</th><th>Original quantity</th><th>Deleted by / date</th><th>Reason</th></tr></thead><tbody>${records.map(r=>`<tr><td>${r.kind}<span class="sub mono">${esc(r.id)}</span></td><td>${esc(r.productCode)}<span class="sub">${esc(r.productName)}</span></td><td>${r.kind==='Delivery'?r.ctn+' Supplier CTN':r.pcs+' finished PCS'}</td><td>${esc(r.voidedBy)}<span class="sub">${date(r.voidedAt)}</span></td><td>${esc(r.voidReason)}</td></tr>`).join('')}</tbody></table></div>`:empty('No deleted records','Voided deliveries and collections appear here. Deleted products remain in the audit log.');
}
function outstandingPanel(){
 const rows=filtered(openTasks(s));
 return panel('Open collection tasks',toolbar(false)+(rows.length?`<div class="tablewrap"><table><thead><tr><th>Product / task</th><th>Packer</th><th>Delivered</th><th>Expected collection</th><th>Collected</th><th>Approved Damage & Loss</th><th>Pending review</th><th>Outstanding collection</th><th>Action</th></tr></thead><tbody>${rows.map(t=>{const n=taskSummary(s,t);return `<tr><td><strong>${esc(t.productName)}</strong><span class="sub">${esc(t.productCode)}</span><span class="sub mono">${esc(t.id)}</span></td><td>${esc(name(t.packerId))}</td><td>${date(t.occurredAt)}<span class="sub">${t.ctn} Supplier CTN</span></td><td>${balanceText(t.expected,t)}</td><td>${balanceText(n.received,t)}<span class="sub">${fmt(n.received)} finished PCS</span></td><td>${fmt(n.approvedEA)} EA</td><td>${fmt(n.pendingEA)} EA${n.pendingEA?'<span class="sub">Not deducted yet</span>':''}</td><td><strong>${fmt(Math.round(n.outstandingEA))} EA</strong><span class="sub">${balanceText(n.outstandingPcs,t)}</span>${n.pendingEA?`<button class="btn small" data-outstandingreview="${esc(t.productCode)}">Review reports</button>`:''}</td><td><details class="record-action"><summary>Action</summary><button class="btn small" data-adminloss="${t.id}">Damage & Loss</button></details></td></tr>`;}).join('')}</tbody></table></div>`:empty('No outstanding collections','All active tasks have been collected or closed by approved Damage & Loss.')));
}
function adminNavigation(items){
 const item=id=>{const entry=items.find(n=>n[0]===id);if(!entry)return '';const [key,ico,label]=entry,pending=key==='confirmations'?s.returns.filter(r=>r.status!=='confirmed').length:0;return `<button data-nav="${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${icon(ico)}<span>${esc(label)}</span>${pending?`<b class="count">${pending}</b>`:''}</button>`;};
 return primaryAdminPages.map(item).join('')+adminMenuGroups.map(group=>{const expanded=Object.hasOwn(menuOpen,group.id)?menuOpen[group.id]:group.pages.includes(page);return `<details class="admin-menu-group" data-navgroup="${group.id}" ${expanded?'open':''}><summary>${icon(group.id==='management'?'grid':'file')}<span>${group.label}</span></summary><div class="admin-submenu">${group.pages.map(item).join('')}</div></details>`;}).join('');
}
function adminLossForm(taskId){
 if(actor.role!=='admin'||reviewing())return;
 const t=s.tasks.find(t=>t.id===taskId);if(!t)return;const n=taskSummary(s,t),total=Math.round(n.outstandingEA),available=n.reportableEA;
 modal('Damage & Loss',`<p><strong>${esc(t.productCode)} · ${esc(t.productName)}</strong><br>${esc(name(t.packerId))}</p><div class="notice"><span>Outstanding: <strong>${fmt(total)} EA</strong>${n.pendingEA?`<br>${fmt(n.pendingEA)} EA reserved by pending reports. Review those reports separately.`:''}<br>Type: Damage & Loss · Applied immediately by Admin · No packaging fee.</span></div>${field('QUANTITY (EA)','adminlossqty',available,'number',`min="1" max="${available}" step="1"`)}<div id="adminlossremaining" role="status" aria-live="polite"></div>`,'<button class="btn primary" id="confirmadminloss">Confirm Damage & Loss</button>');
 const update=()=>{const qty=Number($('#adminlossqty').value),valid=Number.isSafeInteger(qty)&&qty>0&&qty<=available;$('#confirmadminloss').disabled=!valid;$('#adminlossremaining').textContent=valid?(total===qty?'Remaining: 0 EA · Case closed':'Remaining: '+fmt(total-qty)+' EA'):(available?'Enter a whole quantity between 1 and '+fmt(available)+' EA.':'No unreserved EA. Review pending reports first.');};
 $('#adminlossqty').oninput=update;update();
 $('#confirmadminloss').onclick=()=>action(async()=>{const qty=Number($('#adminlossqty').value);if(!Number.isSafeInteger(qty)||qty<1||qty>available)throw Error('Enter a valid EA quantity.');$('#confirmadminloss').disabled=true;try{await mutate('resolveLoss',{taskId,qty});const current=s.tasks.find(t=>t.id===taskId),left=current?Math.round(taskSummary(s,current).outstandingEA):0;modalClose();toast(left?'Damage & Loss recorded. Remaining: '+fmt(left)+' EA.':'Damage & Loss recorded. Remaining: 0 EA · Case closed.');}catch(e){update();throw e;}});
}
